// Get alerts - referenciando explícitamente al Nodo 1
const alertItems = $('1. Obtener Alertas').all();

// Get providers - referenciando el input actual (que viene del Nodo 2)
const providerItems = $input.all();
const proveedoresMap = {};

// Safely build the map
for (let i = 0; i < providerItems.length; i++) {
  const prov = providerItems[i].json;
  if (prov && prov.id) {
    proveedoresMap[prov.id] = prov;
  }
}

// Filter items that need reorder
const criticos = [];
for (let i = 0; i < alertItems.length; i++) {
  const item = alertItems[i].json;
  // Convertimos a booleano explícito por seguridad (en caso de que venga como string 'true')
  if (item && (item.necesita_reorden === true || item.necesita_reorden === 'true')) {
    criticos.push(item);
  }
}

// If there are critical items, create orders
if (criticos.length > 0) {
  const results = [];
  for (let i = 0; i < criticos.length; i++) {
    const insumo = criticos[i];
    const provId = insumo.proveedor_id;
    const proveedor = proveedoresMap[provId] || null;

    results.push({
      json: {
        tiene_orden: true,
        insumo_id: insumo.id,
        insumo_nombre: insumo.nombre,
        stock_actual: insumo.stock_actual,
        stock_minimo: insumo.stock_minimo,
        unidad_medida: insumo.unidad_medida,
        proveedor_id: provId,
        proveedor_nombre: proveedor ? String(proveedor.nombre) : 'Sin proveedor',
        proveedor_email: proveedor ? String(proveedor.email || '') : '',
        cantidad_a_ordenar: Math.ceil((insumo.stock_minimo * 2) - insumo.stock_actual),
        fecha_orden: new Date().toISOString().split('T')[0]
      }
    });
  }
  return results;
}

// No critical items - return message
return [{
  json: {
    tiene_orden: false,
    mensaje: 'No hay insumos bajo stock minimo'
  }
}];

