// Process ALL items (not just the first one)
const items = $input.all();
const insumos = $('3. Procesar Insumos').all();

// Create a map of insumos for quick lookup
const insumosMap = {};
for (let i = 0; i < insumos.length; i++) {
  const insumo = insumos[i].json;
  insumosMap[insumo.insumo_id] = insumo;
}

// Process each order result
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const insumo = insumosMap[item.insumo_id] || {};

  results.push({
    json: {
      orden_id: item.id || 'N/A',
      insumo_nombre: String(insumo.insumo_nombre || 'Unknown'),
      proveedor_nombre: String(insumo.proveedor_nombre || 'Unknown'),
      cantidad: item.cantidad || insumo.cantidad_a_ordenar,
      unidad_medida: String(insumo.unidad_medida || ''),
      mensaje: 'Orden creada: ' + (insumo.cantidad_a_ordenar || '?') + ' ' + (insumo.unidad_medida || '') + ' de ' + (insumo.insumo_nombre || 'Unknown')
    }
  });
}

return results;

const item = $input.first().json;
return [{
  json: {
    mensaje: 'Sin ordenes: ' + String(item.mensaje),
    status: 'OK'
  }
}];
